// Embeds lib/report-template.html as a TS string so it ships inside the serverless bundle.
import fs from 'node:fs';
const html = fs.readFileSync(new URL('../lib/report-template.html', import.meta.url), 'utf8');
fs.writeFileSync(new URL('../lib/report-template.generated.ts', import.meta.url),
  '// GENERATED by scripts/embed-template.mjs. Edit lib/report-template.html instead.\nexport const REPORT_TEMPLATE = ' + JSON.stringify(html) + ';\n');
